import socket
import asyncore
import six


class UDPListener(asyncore.dispatcher):
    """A class for starting a UDP listener (UDP server) on the specified ip and port.

    A callback method is used to forward received data to the object that started this listener. Socket is bound with the REUSE option,
    which means that it is possible to close and restart the listener without any delay.
    """
    def __init__(self, ip, port, callback):
        """
        :param string  ip:   IP address to bind.
        :param integer port: UDP port to bind.
        :param callback:     Method needed to forward received data to the object that started this listener.
        """
        asyncore.dispatcher.__init__(self)
        self._ip = ip
        self._port = port
        self._callback = callback
        self._create_socket_and_bind()

    def writable(self):
        """Called each time around the asynchronous loop to determine whether a channel's socket should be added to the list
           on which write events can occur."""
        return 0

    def handle_read(self):
        """Method to receive and forward data.

        :note: Max. buffer for socket is set to 8192 Bytes.
        """
        (data, addr) = self.socket.recvfrom(8192)
        if six.PY3:
            data = data.decode("utf-8", errors="ignore")
        if data and addr:
            trace = "[{}] {}".format(addr[0], data.rstrip('\0'))
            trace = trace.rstrip("\r\n")
            trace = trace.replace("\n", "\n[{}] ".format(addr[0]))
            self._callback(trace)

    def _create_socket_and_bind(self):
        self.create_socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.set_reuse_addr()
        self.bind((self._ip, self._port))
